const entrada = $('When Executed by Another Workflow').first().json;

// Destino de cada loja. Por enquanto todos vão para o número de teste.
// Quando os grupos existirem, troque pelo ID do grupo (termina em @g.us).
const destinos = {
  'osasco':      '5511975881489@s.whatsapp.net',
  'carapicuiba': '5511975881489@s.whatsapp.net',
  'jundiai':     '5511975881489@s.whatsapp.net',
  'sao miguel':  '5511975881489@s.whatsapp.net',
};
// Se a loja não vier ou não for reconhecida, vai para cá.
const padrao = '5511975881489@s.whatsapp.net';

const loja = (entrada.loja || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim();
const chave = Object.keys(destinos).find(k => loja.includes(k));

const titulo = entrada.tipo === 'lembrete'
  ? '⏰ *Lembrete: este cliente ainda aguarda retorno*'
  : '🛋️ *Cliente pronto para comprar*';

const texto = [
  titulo,
  `*Nome:* ${entrada.nome || '-'}`,
  `*WhatsApp:* https://wa.me/${entrada.telefone}`,
  `*Produtos:* ${entrada.produtos || '-'}`,
  `*Loja:* ${entrada.loja || '-'}`,
  `*Resumo:* ${entrada.resumo || '-'}`,
].join('\n');

return [{ json: {
  remoteJid: chave ? destinos[chave] : padrao,
  loja_identificada: chave || 'nenhuma',
  texto,
} }];

